     {zh:'做点儿你力所能及的事情吧，难度太大的就不要做了。',py:'Zuò diǎnr nǐ lìsuǒnéngjí de shìqing ba, nándù tài dà de jiù bú yào zuò le.',vn:'Làm những việc trong khả năng của con thôi, việc khó quá thì đừng làm.'},
     {zh:'孩子应该在家里做一些力所能及的家务。',py:'Háizi yīnggāi zài jiā li zuò yìxiē lìsuǒnéngjí de jiāwù.',vn:'Trẻ con nên làm một số việc nhà vừa sức ở nhà.'}
