     {zh:'据史书记载，这座桥已经有一千多年的历史了。',py:'Jù shǐshū jìzǎi, zhè zuò qiáo yǐjīng yǒu yìqiān duō nián de lìshǐ le.',vn:'Theo sử sách ghi chép, cây cầu này đã có lịch sử hơn một nghìn năm.'},
     {zh:'有些动物，我们的后代可能只有在文字记载中去了解了。',py:'Yǒuxiē dòngwù, wǒmen de hòudài kěnéng zhǐyǒu zài wénzì jìzǎi zhōng qù liǎojiě le.',vn:'Có những loài động vật mà con cháu chúng ta có lẽ chỉ còn tìm hiểu được qua sách vở ghi chép.'}
