   usage:'时常 + V (时常煮面条, 时常打电话). Đồng nghĩa 常常 / 经常; 时常 thường chỉ việc lặp lại không đều đặn lắm.',
   collo:['时常煮面条','时常打电话','时常想起','时常见面'],
