var speakingData = {
  intro:'Đây là bài tập 5 trong sách: <b>根据提示，简述课文主要内容</b>. Mỗi câu hỏi là một dòng của bảng — bấm loa nghe câu hỏi, nhìn gợi ý bên phải, <b>tự ghi âm câu trả lời của mình trước</b> rồi mới mở câu mẫu. Cố dùng từ mới: 典型 · 毅然 · 疲惫 · 鼓动 · 遭遇 · 惊奇 · 刻不容缓 · 精打细算 · 将就.',
  questions:[
    {q_zh:'简述一下王建男的工作经历。',
     q_vn:'Hãy kể tóm tắt quá trình làm việc của Vương Kiến Nam.',
     hint:'①大学毕业做过…… ②领导的报社成为…… ③身心疲惫，毅然决定……',
     sample:'王建男大学毕业做过摄影记者、新闻评论员和编辑，50岁做了社长。他领导的报社成为中国报业改革的典型，每天都有一拨拨同行来考察访问。可是就在事业达到高峰的时候，他身心疲惫，毅然决定离开报社。',
     sample_vn:'Tốt nghiệp đại học, Vương Kiến Nam từng làm phóng viên ảnh, bình luận viên tin tức và biên tập viên, 50 tuổi làm xã trưởng. Tòa báo ông lãnh đạo trở thành điển hình của cải cách ngành báo chí Trung Quốc, ngày nào cũng có hết tốp này đến tốp khác đồng nghiệp đến khảo sát, thăm quan. Nhưng đúng lúc sự nghiệp lên tới đỉnh cao, ông thân tâm rã rời, kiên quyết rời tòa báo.',
     note:'Đi đủ ba gợi ý ①②③ theo thứ tự thời gian; 就在……的时候 làm nổi bật bước ngoặt; 一拨拨 = hết tốp này đến tốp khác.'},
    {q_zh:'辞职后，王建男有什么经历？',
     q_vn:'Sau khi nghỉ việc, Vương Kiến Nam đã trải qua những gì?',
     hint:'先是……，不久……，再后来……',
     sample:'辞职后，王建男一身轻松。他先是办了家企业；不久他跨洋过海，到了加拿大；再后来，他恋上了北极，在妻子的鼓动下，夫妇俩出发去了北极。',
     sample_vn:'Nghỉ việc rồi, Vương Kiến Nam thấy nhẹ nhõm cả người. Đầu tiên ông mở một doanh nghiệp; không lâu sau vượt đại dương sang Canada; về sau nữa ông phải lòng Bắc Cực, và được vợ khích lệ, hai vợ chồng lên đường đi Bắc Cực.',
     note:'Khung 先是……，不久……，再后来…… kể ba sự việc nối tiếp; có thể thêm 在……的鼓动下 để nối sang chuyến đi.'},
    {q_zh:'书中一般是怎样描述北极的？',
     q_vn:'Sách vở thường miêu tả Bắc Cực như thế nào?',
     hint:'大约4000年前……，途中遭遇……，最终退进……，住……，用……，……生存下来',
     sample:'书中说，大约4000年前，最后一批亚裔族群跨过白令海峡，向美洲进发，途中遭遇印第安人的围堵，最终退进气候恶劣的北极圈。他们住雪屋，用长矛打猎，在饥饿、风暴、严寒中奇迹般地生存下来。',
     sample_vn:'Sách kể rằng khoảng 4000 năm trước, nhóm tộc người gốc Á cuối cùng vượt eo biển Bering tiến về châu Mỹ, giữa đường gặp phải sự vây chặn của người da đỏ, cuối cùng lui vào vòng Bắc Cực khí hậu khắc nghiệt. Họ ở nhà tuyết, dùng giáo dài săn bắn, sống sót một cách kỳ diệu giữa đói khát, bão tố và giá rét.',
     note:'Nói theo đúng chuỗi động từ của gợi ý: 遭遇 → 退进 → 住 → 用 → 生存下来; 奇迹般地 = một cách kỳ diệu.'},
    {q_zh:'现实的北极是什么样的？',
     q_vn:'Bắc Cực ngoài thực tế như thế nào?',
     hint:'①屋内…… ②连锁超市…… ③年轻人……',
     sample:'到了北极，他们惊奇地发现，现实和书中的差别竟如此之大：屋内温暖如春，家电齐全，户户都能上网；连锁超市里卖的是包装食品；年轻人穿着时髦的衣裳，潇洒而快活。',
     sample_vn:'Đến Bắc Cực, họ kinh ngạc phát hiện thực tế và sách vở khác nhau lớn đến vậy: trong nhà ấm áp như mùa xuân, đồ điện đầy đủ, nhà nào cũng lên mạng được; chuỗi siêu thị bán thực phẩm đóng gói; thanh niên mặc quần áo thời thượng, phóng khoáng và vui vẻ.',
     note:'Mở đầu bằng 惊奇地发现……差别竟如此之大 rồi liệt kê ba ý, ngăn cách bằng dấu ；.'},
    {q_zh:'现在，王建男专注于什么事情？',
     q_vn:'Hiện nay Vương Kiến Nam chuyên chú vào việc gì?',
     hint:'不再在意……，只专注于……，采访专题……',
     sample:'现在，王建男不再在意自然风光和千奇百怪的动植物，只专注于人文。他的镜头中有捕捉动物的妇人，有赤道血统的北极姑娘。他的采访专题是“北极人文圈”，因为他知道抢救正在消失的东西刻不容缓。',
     sample_vn:'Hiện nay Vương Kiến Nam không còn bận tâm đến cảnh sắc thiên nhiên và muôn loài động thực vật kỳ lạ, chỉ chuyên chú vào con người và văn hóa. Trong ống kính của ông có người phụ nữ bắt thú, có cô gái Bắc Cực mang dòng máu xứ xích đạo. Chuyên đề phỏng vấn của ông là "Vòng nhân văn Bắc Cực", vì ông biết cứu vãn những thứ đang biến mất là việc không thể chậm trễ.',
     note:'不再……，只…… đối lập cái bỏ và cái giữ; kết bằng lý do 因为……刻不容缓.'},
    {q_zh:'为了节省开支，王建男夫妇采取了什么措施？',
     q_vn:'Để tiết kiệm chi tiêu, vợ chồng Vương Kiến Nam đã áp dụng những biện pháp gì?',
     hint:'处处……，租用……，自带药品，将就将就……',
     sample:'他们处处精打细算，千方百计节省开支，免得储蓄减少得太快。即使穿越无人区，他们也只租用最便宜的汽车；生病了就用自带的药品；吃饭时常煮一锅面条，放点儿蔬菜和肉酱，将就将就就是一餐。',
     sample_vn:'Họ chỗ nào cũng tính toán chi li, tìm mọi cách tiết kiệm chi tiêu, để tiền dành dụm khỏi vơi đi quá nhanh. Cho dù băng qua vùng không người, họ cũng chỉ thuê loại ô tô rẻ nhất; ốm thì dùng thuốc mang theo; bữa ăn thường nấu một nồi mì, cho ít rau và tương thịt, tạm bợ thế là xong một bữa.',
     note:'Dùng 处处……，免得…… và 即使……也……; 将就将就就是一餐 có hai chữ 就 liền nhau: 将就 (tạm) + 就是 (là).'}
  ]
};

